// Minimal API — CancellationToken parameter is bound automatically
app.MapGet("/reports/{id:int}", async Task<Results<Ok<Report>, ProblemHttpResult>> (
    int id,
    ReportDb db,
    IReportClient upstream,          // internal microservice client
    CancellationToken requestAborted) // == HttpContext.RequestAborted
{
    // Link the client's cancellation with a hard 10s budget of our own
    using var linked = CancellationTokenSource.CreateLinkedTokenSource(requestAborted);
    linked.CancelAfter(TimeSpan.FromSeconds(10));
    var ct = linked.Token;

    try
    {
        // Every layer observes the same token:
        var meta = await db.Reports.AsNoTracking()
            .FirstOrDefaultAsync(r => r.Id == id, ct);            // EF cancels the query

        if (meta is null) return Results.NotFound();

        var rows = await upstream.FetchRowsAsync(id, ct);          // HttpClient aborts on cancel

        await db.Audit.AddAsync(new Audit(id, rows.Count), ct);
        await db.SaveChangesAsync(ct);                             // must not half-commit: transactional anyway

        return Results.Ok(new Report(rows));
    }
    catch (OperationCanceledException) when (requestAborted.IsCancellationRequested)
    {
        // Client hung up — expected, not a server error. Don't log as failure.
        return Results.Problem(statusCode: 499, title: "Client closed request");
    }
    catch (OperationCanceledException)
    {
        // Our 10s budget expired — a real timeout worth reporting
        return Results.Problem(statusCode: 504, title: "Upstream report timed out");
    }
});

